"""Article-specific editorial source for CC-08 (Civil Code arts. 521-550)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {
        "target": target,
        "o_que_diz": says,
        "o_que_significa": means,
        "exemplo_pratico": example,
        "atencao": warning,
        "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}],
    }


ROWS = {
    "521": row("Na venda de bem móvel, o vendedor pode conservar a propriedade até receber todo o preço.", "A cláusula separa entrega e domínio: o comprador recebe a coisa, mas só se torna proprietário após a quitação integral. A técnica reforça a garantia do crédito do vendedor.", "Loja entrega uma máquina parcelada e reserva o domínio até a última prestação.", "A reserva deve observar as formalidades dos artigos seguintes. Ela não significa que o vendedor suporte os riscos depois da entrega.", "Reserva de domínio", "cláusula pela qual o vendedor mantém a propriedade até o pagamento completo"),
    "522": row("A reserva de domínio precisa constar de documento escrito e ser registrada no domicílio do comprador para produzir efeitos perante terceiros.", "O escrito estabelece a cláusula entre os contratantes. O registro dá publicidade e permite que o vendedor invoque sua propriedade contra pessoas estranhas ao negócio.", "Contrato escrito de veículo financiado é registrado no domicílio do comprador para tornar pública a reserva.", "Sem registro, a cláusula pode vincular as partes, mas não é oponível a terceiros. O artigo não dispensa outras formalidades eventualmente aplicáveis ao bem.", "Oponibilidade", "possibilidade de fazer um direito valer contra terceiros"),
    "523": row("Somente bem perfeitamente identificável pode ser vendido com reserva de domínio; dúvida sobre a individualização favorece terceiro adquirente de boa-fé.", "A garantia deve recair sobre objeto distinguível dos semelhantes. Sem identificação segura, o antigo vendedor não pode retirar de terceiro de boa-fé coisa cuja origem seja incerta.", "Equipamento com número de série pode ser individualizado; mercadoria genérica misturada ao estoque pode não atender ao requisito.", "A identificação deve permitir separar exatamente o bem. Má-fé do terceiro afasta a proteção específica baseada na dúvida.", "Caracterização perfeita", "identificação suficiente para distinguir uma coisa de todas as congêneres"),
    "524": row("Na reserva de domínio, a propriedade passa ao comprador com a quitação, mas os riscos da coisa são dele desde a entrega.", "Embora o vendedor ainda seja proprietário para fins de garantia, perda ou deterioração posterior à entrega não elimina, por si só, o dever do comprador de pagar.", "Máquina entregue é destruída por evento fortuito antes da última parcela; o risco permanece com o comprador.", "A regra pressupõe entrega e deve ser conjugada com culpa, mora, seguro e outras normas aplicáveis. Propriedade reservada e responsabilidade pelo risco seguem marcos diferentes.", "Risco da coisa", "responsabilidade econômica por perda ou deterioração fortuita do bem"),
    "525": row("O vendedor só pode acionar a reserva de domínio depois de constituir o comprador em mora por protesto do título ou interpelação judicial.", "O inadimplemento isolado não autoriza imediatamente a retomada fundada nessa cláusula. É necessário formalizar a mora por uma das vias indicadas.", "Comprador atrasa parcelas; antes de pedir a recuperação do bem, o vendedor promove o protesto do título.", "A exigência é própria da execução da reserva de domínio. O ato escolhido deve ser válido e identificar adequadamente a obrigação vencida.", "Interpelação judicial", "comunicação realizada em juízo para exigir cumprimento e produzir efeitos jurídicos"),
    "526": row("Constituída a mora, o vendedor pode cobrar parcelas vencidas, vincendas e demais valores devidos, ou buscar a recuperação da posse do bem.", "A norma oferece caminhos alternativos: exigir o crédito abrangido pelo contrato ou retomar a coisa cuja propriedade foi reservada. A escolha repercute na liquidação prevista no artigo seguinte.", "Após formalizar a mora, vendedor opta por ação de cobrança em vez de recuperar o equipamento.", "As medidas devem seguir a legislação processual. A cobrança de parcelas futuras e outros valores depende do título e dos limites jurídicos aplicáveis.", "Prestações vincendas", "parcelas cujo vencimento ainda ocorreria no futuro"),
    "527": row("Se recuperar a coisa, o vendedor pode reter do que foi pago apenas o necessário para depreciação, despesas e créditos legítimos, devolvendo o excedente ou cobrando a diferença.", "A retomada exige acerto de contas. O vendedor não fica automaticamente com o bem e com todas as parcelas: deve justificar os abatimentos e apurar o saldo conforme o processo aplicável.", "Bem retomado depreciou menos que as parcelas pagas; descontados gastos e dívida, o restante volta ao comprador.", "A retenção não é penalidade ilimitada. Depreciação, despesas e demais créditos precisam ser demonstrados, evitando enriquecimento sem causa.", "Depreciação", "redução do valor econômico da coisa pelo uso, tempo ou desgaste"),
    "528": row("Quando instituição do mercado de capitais financia o preço recebido pelo vendedor, ela exerce os direitos e ações contratuais em benefício do interessado; financiamento e ciência do comprador devem constar do registro.", "O crédito e as garantias operacionais passam a ser exercidos pela financiadora, desde que a estrutura financeira e o conhecimento do comprador recebam publicidade registral.", "Financeira paga o vendedor à vista e passa a cobrar as parcelas garantidas pela reserva registrada.", "O registro deve revelar a operação e a ciência do comprador. A norma não autoriza cobrança além do contrato nem elimina defesas legalmente cabíveis.", "Instituição do mercado de capitais", "entidade autorizada que participa do financiamento da operação"),
    "529": row("Na venda sobre documentos, a entrega dos papéis representativos substitui a entrega material da mercadoria; com documentação regular, o comprador normalmente não pode suspender o pagamento por alegar defeito ainda não comprovado.", "A operação circula por títulos e documentos, comum quando a mercadoria está em trânsito. A conferência documental vem antes da inspeção física, ressalvada prova já existente do defeito.", "Carga marítima é negociada pela entrega do conhecimento e dos documentos exigidos.", "Documentos em ordem não eliminam garantias por defeito. A exceção permite recusa quando o problema de qualidade ou estado já está comprovado.", "Título representativo", "documento que permite controlar ou reclamar a entrega da mercadoria"),
    "530": row("Sem cláusula diferente, o comprador paga no mesmo momento e local em que recebe os documentos da venda.", "A regra supletiva sincroniza pagamento e entrega documental. As partes podem convencionar outro marco ou lugar.", "Banco entrega os documentos comerciais ao comprador e recebe o valor naquela ocasião.", "A norma vale no silêncio do contrato. Deve-se distinguir entrega dos documentos de chegada física da mercadoria, que pode ocorrer depois.", "Regra supletiva", "norma aplicada quando as partes não estipulam solução diferente"),
    "531": row("Se os documentos incluem seguro do transporte, o risco coberto fica com o comprador, salvo quando o vendedor já sabia da perda ou avaria ao contratar.", "A apólice permite ao comprador buscar a cobertura e justifica atribuir-lhe o risco. O vendedor não pode transferir consequência de dano que conhecia e ocultou na formação do negócio.", "Mercadoria segurada sofre avaria no percurso; o comprador aciona o seguro, desde que o vendedor não soubesse previamente do dano.", "É necessário conferir cobertura, momento do dano e conhecimento do vendedor. A simples presença de apólice não cobre risco excluído do seguro.", "Apólice", "documento que formaliza o contrato e as coberturas do seguro"),
    "532": row("Se o pagamento foi atribuído a banco, ele paga contra documentos e não precisa examinar a mercadoria; o vendedor só cobra diretamente do comprador depois de recusa bancária.", "O banco atua no plano documental, sem assumir responsabilidade pela qualidade da coisa. A cobrança direta é subsidiária à tentativa perante a instituição indicada.", "Banco recusa documentos desconformes; somente então o vendedor busca o preço do comprador.", "A ausência de verificação da coisa não dispensa o banco de conferir os documentos segundo o ajuste. A responsabilidade do vendedor pelo bem permanece.", "Pagamento documentário", "pagamento condicionado à apresentação dos documentos previstos na operação"),
    "533": row("A permuta segue, em geral, as regras da compra e venda; salvo ajuste diverso, cada parte arca com metade das despesas do instrumento, e troca desigual entre ascendente e descendente exige os consentimentos legais.", "Cada contratante entrega um bem em troca de outro. A lei adapta o regime quanto aos custos e protege herdeiros e cônjuge quando há desigualdade de valores na relação familiar.", "Pai troca imóvel mais valioso por bem do filho sem consentimentos exigidos; o negócio pode ser anulado.", "A sanção indicada para a troca familiar desigual é anulabilidade, não nulidade automática. É preciso apurar valores e consentimentos.", "Permuta", "contrato em que as partes trocam bens sem que o núcleo seja pagamento em dinheiro"),
    "534": row("No contrato estimatório, o consignante entrega bem móvel ao consignatário, que pode vendê-lo e pagar o valor ajustado ou devolvê-lo no prazo.", "O consignatário recebe poder de disposição, mas assume alternativa definida: entregar o preço estimado ou restituir a própria coisa tempestivamente.", "Galeria recebe obra para venda; se não a negociar no prazo, devolve-a ao artista.", "Não é simples mandato nem compra e venda definitiva desde a entrega. A restituição deve observar prazo e integridade, conforme o artigo seguinte.", "Consignatário", "quem recebe bens para vendê-los, pagando o preço estimado ou devolvendo-os"),
    "535": row("O consignatário continua obrigado a pagar o preço se não puder devolver a coisa íntegra, mesmo quando a impossibilidade não decorre de culpa sua.", "Ele assume o risco da restituição. A perda ou dano que inviabiliza devolver o bem nas condições recebidas converte sua posição na obrigação de pagar o valor combinado.", "Peça consignada é destruída fortuitamente; o consignatário ainda deve o preço estimado.", "A regra é mais rigorosa que a responsabilidade comum por culpa. Seguro e direito regressivo contra terceiro não eliminam o dever perante o consignante.", "Risco da restituição", "responsabilidade por não conseguir devolver a coisa nas condições juridicamente exigidas"),
    "536": row("Enquanto o preço não for integralmente pago, credores do consignatário não podem penhorar ou sequestrar o bem consignado.", "A coisa permanece protegida porque não integra livremente o patrimônio que garante as dívidas do consignatário. A restrição dura até a quitação do preço.", "Credor da loja não pode penhorar joia recebida em consignação e ainda não paga ao proprietário.", "A proteção exige demonstrar o contrato e identificar a coisa. Depois do pagamento integral, muda a base patrimonial relevante.", "Sequestro", "medida judicial de apreensão e guarda de bem objeto de disputa ou risco"),
    "537": row("O consignante não pode alienar ou onerar a coisa enquanto ela não for devolvida, nem antes de receber comunicação de que será restituída.", "Durante a consignação, o consignatário possui autorização para vender. Para não frustrar essa posição, o proprietário fica temporariamente impedido de dispor do bem.", "Fornecedor não vende a terceiro produto ainda exposto pelo consignatário sem restituição comunicada.", "A simples vontade do consignante não encerra o contrato fora de seus termos. Deve haver restituição efetiva ou comunicação juridicamente adequada.", "Dispor da coisa", "alienar, gravar ou praticar ato que afete juridicamente o bem"),
    "538": row("Doação é o contrato pelo qual alguém, por liberalidade, transfere bem ou vantagem do próprio patrimônio para outra pessoa.", "O instituto combina intenção gratuita e deslocamento patrimonial. Doador e donatário ocupam posições contratuais, sujeitas às regras de aceitação, forma e limites legais.", "Pessoa transfere gratuitamente um imóvel a uma entidade assistencial, que aceita a liberalidade.", "Nem toda vantagem gratuita é doação. É preciso verificar a estrutura do ato, a diminuição patrimonial e eventual disciplina especial.", "Liberalidade", "atribuição voluntária de vantagem sem contraprestação equivalente"),
    "539": row("O doador pode dar prazo para o donatário aceitar; se este conhece o prazo e permanece em silêncio, a doação pura é considerada aceita.", "A lei atribui efeito positivo ao silêncio apenas quando não há encargo e o destinatário foi informado do prazo. A regra facilita a conclusão de liberalidade exclusivamente benéfica.", "Doador fixa dez dias para aceitação de quantia sem encargo; o donatário informado não responde e a aceita tacitamente.", "Silêncio não vale como aceitação de doação onerada por encargo. Ciência do prazo e ausência de manifestação também precisam ser comprovadas.", "Aceitação tácita", "concordância inferida de comportamento ou silêncio ao qual a lei atribui efeito"),
    "540": row("Doação motivada pelo mérito do beneficiário, remuneratória ou com encargo continua gratuita na parcela que excede serviço recompensado ou obrigação imposta.", "A presença de motivo, recompensa ou dever acessório não elimina necessariamente a liberalidade. Se a vantagem supera a contrapartida econômica, o excedente conserva natureza de doação.", "Cliente transfere bem de valor superior ao serviço prestado; a diferença constitui liberalidade remuneratória.", "É necessário separar a parcela remuneratória ou onerosa do excedente gratuito, pois os efeitos jurídicos podem variar entre elas.", "Doação remuneratória", "liberalidade feita em reconhecimento a serviço que não constitui dívida exigível equivalente"),
    "541": row("A doação deve ser formalizada por escritura pública ou instrumento particular; a verbal só vale para móvel de pequeno valor entregue imediatamente.", "A regra geral exige documento. A exceção reúne três elementos: acordo verbal, bem móvel de reduzido valor e tradição logo após a declaração.", "Pessoa oferece verbalmente livro de pequeno valor e o entrega no mesmo momento; a forma excepcional pode ser válida.", "Pequeno valor é avaliado no contexto patrimonial e concreto. Doação verbal de imóvel ou sem entrega imediata não se enquadra na exceção.", "Tradição imediata", "entrega da coisa realizada sem intervalo relevante após o acordo"),
    "542": row("A doação destinada a nascituro produz efeitos se seu representante legal a aceitar.", "Embora ainda não tenha nascido, o beneficiário concebido pode receber a liberalidade mediante atuação representativa, preservando-se seus interesses.", "Pais aceitam, em nome do filho concebido, doação feita por um avô.", "A norma exige nascituro e aceitação por representante legal. A consolidação dos efeitos deve ser compatibilizada com as regras gerais sobre direitos do concebido.", "Nascituro", "ser humano já concebido, mas ainda não nascido"),
    "543": row("Na doação pura a pessoa absolutamente incapaz, a aceitação é dispensada.", "Como o negócio só beneficia o donatário e não lhe impõe encargo, a lei evita que a incapacidade impeça a aquisição gratuita.", "Criança recebe quantia sem qualquer obrigação; não é necessária declaração de aceitação em seu nome para essa regra.", "A dispensa depende de doação pura. Havendo encargo, condição onerosa ou risco de prejuízo, aplicam-se representação e controles próprios.", "Doação pura", "liberalidade sem encargo ou contraprestação exigida do donatário"),
    "544": row("Doação de ascendente a descendente, ou entre cônjuges, é tratada como antecipação da herança que caberá ao beneficiário.", "O valor recebido deve ser considerado na futura sucessão, permitindo equalizar as legítimas conforme as regras de colação e partilha.", "Mãe doa imóvel a um filho; na sucessão, o bem pode integrar o cálculo do adiantamento hereditário.", "A norma não declara a doação inválida. Dispensa de colação, parte disponível, regime de bens e outras regras sucessórias exigem análise própria.", "Adiantamento da legítima", "atribuição feita em vida que antecipa parcela reservada ao herdeiro necessário"),
    "545": row("Subvenção doada em pagamentos periódicos termina com a morte do doador, salvo disposição diferente, e jamais pode continuar além da vida do donatário.", "A prestação sucessiva tem limite pessoal. O doador pode prever continuidade após sua morte, mas somente enquanto viver o beneficiário.", "Doador promete auxílio mensal vitalício ao donatário e prevê que seu espólio continue pagando; o dever cessa com a morte do beneficiário.", "A cláusula pode alterar o efeito da morte do doador, não o limite ligado à vida do donatário. Deve-se examinar fonte de pagamento e forma da liberalidade.", "Subvenção periódica", "auxílio gratuito pago em prestações sucessivas"),
    "546": row("Doação feita em consideração a casamento futuro determinado não pode ser contestada por falta de aceitação e perde efeito se o casamento não ocorrer.", "A celebração do casamento indicado funciona como pressuposto da liberalidade. A regra alcança doações entre nubentes ou de terceiro a um deles, ao casal ou aos futuros filhos comuns.", "Avó doa bem ao casal em vista do casamento marcado; se a união não for celebrada, a doação fica sem efeito.", "O casamento precisa ser com a pessoa determinada. A dispensa de impugnação por falta de aceitação não afasta forma, capacidade e outros requisitos legais.", "Doação propter nuptias", "doação realizada em consideração a casamento futuro específico"),
    "547": row("O doador pode prever retorno do bem ao próprio patrimônio se sobreviver ao donatário, mas não pode estabelecer reversão em favor de terceiro.", "A cláusula resolutiva protege pessoalmente o doador: com a morte anterior do beneficiário, o bem volta a quem doou. Não serve para transferi-lo automaticamente a outra pessoa.", "Pai doa imóvel ao filho e estipula retorno caso o filho morra primeiro; sobrevivendo o pai, ocorre a reversão.", "A reversão depende de estipulação e da sobrevivência do doador. Sem ela, o bem segue o regime patrimonial e sucessório do donatário.", "Cláusula de reversão", "previsão de retorno do bem ao doador quando ocorre o evento estipulado"),
    "548": row("É nula a doação de todo o patrimônio quando o doador não conserva bens ou renda suficientes para sua manutenção.", "A lei impede liberalidade universal que deixe o doador sem meios de subsistência. A proteção opera como limite de validade do negócio.", "Pessoa transfere todos os bens e fica sem renda para despesas básicas; a doação é atingida pela nulidade.", "A análise considera reserva efetivamente suficiente, não apenas existência nominal de algum bem. A nulidade não se confunde com simples arrependimento posterior.", "Doação universal", "liberalidade que abrange a totalidade dos bens do doador"),
    "549": row("É nula a parcela da doação que ultrapassa o que o doador poderia deixar por testamento na data do ato.", "A doação inoficiosa invade a parte reservada aos herdeiros necessários. O excesso é reduzido, preservando-se a liberalidade dentro da porção disponível.", "Pessoa com herdeiros necessários doa valor superior à metade disponível; o excedente pode ser invalidado.", "O cálculo usa patrimônio e situação sucessória existentes no momento da doação. A nulidade alcança o excesso, não necessariamente o negócio inteiro.", "Doação inoficiosa", "doação que excede a parcela patrimonial livremente disponível pelo doador"),
    "550": row("A doação feita por cônjuge ao parceiro de relação extraconjugal pode ser anulada pelo outro cônjuge ou por seus herdeiros necessários até dois anos após o fim da sociedade conjugal.", "A norma concede legitimidade específica e fixa prazo contado da dissolução do vínculo conjugal para atacar essa liberalidade.", "Após o divórcio, o ex-cônjuge pede dentro de dois anos a anulação da doação feita ao cúmplice durante o casamento.", "O negócio é anulável, não automaticamente nulo. É preciso provar os pressupostos da regra, a legitimidade de quem demanda e a observância do prazo.", "Sociedade conjugal", "comunhão de vida jurídica criada pelo casamento e encerrada nas hipóteses legais"),
}
